solution.markdown.zig:
const std = @import("std");

// Refactoring separates line structure from inline emphasis and list state.
fn inlineText(out:*std.array_list.Managed(u8),text:[]const u8) anyerror!void {
    var i:usize=0;
    while(i<text.len) {
        if(text[i]=='_') {
            const count:usize=if(i+1<text.len and text[i+1]=='_') 2 else 1;
            const marker=if(count==2) "__" else "_";
            if(std.mem.indexOf(u8,text[i+count..],marker)) |offset| {
                const tag=if(count==2) "strong" else "em";
                try out.append('<');try out.appendSlice(tag);try out.append('>');
                try inlineText(out,text[i+count..i+count+offset]);
                try out.appendSlice("</");try out.appendSlice(tag);try out.append('>');
                i+=count+offset+count;continue;
            }
        }
        try out.append(text[i]);i+=1;
    }
}
pub fn parse(allocator:std.mem.Allocator,markdown:[]const u8) ![]u8 {
    var out=std.array_list.Managed(u8).init(allocator);errdefer out.deinit();
    var lines=std.mem.splitScalar(u8,markdown,'\n');var in_list=false;
    while(lines.next()) |line| {
        const list_item=std.mem.startsWith(u8,line,"* ");
        if(in_list and !list_item) {try out.appendSlice("</ul>");in_list=false;}
        if(list_item) {
            if(!in_list) {try out.appendSlice("<ul>");in_list=true;}
            try out.appendSlice("<li>");try inlineText(&out,line[2..]);try out.appendSlice("</li>");continue;
        }
        var level:usize=0;while(level<line.len and line[level]=='#') : (level+=1) {}
        if(level>=1 and level<=6 and level<line.len and line[level]==' ') {
            try out.appendSlice("<h");try out.append(@as(u8,@intCast(level))+'0');try out.append('>');
            try inlineText(&out,line[level+1..]);
            try out.appendSlice("</h");try out.append(@as(u8,@intCast(level))+'0');try out.append('>');
        } else {try out.appendSlice("<p>");try inlineText(&out,line);try out.appendSlice("</p>");}
    }
    if(in_list)try out.appendSlice("</ul>");return out.toOwnedSlice();
}

