const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("markdown.zig");
test "test_parses_normal_text_as_a_paragraph" {const out=try m.parse(a,"This will be a paragraph");defer a.free(out);try t.expectEqualStrings("<p>This will be a paragraph</p>",out);}
test "test_parsing_italics" {const out=try m.parse(a,"_This will be italic_");defer a.free(out);try t.expectEqualStrings("<p><em>This will be italic</em></p>",out);}
test "test_parsing_bold_text" {const out=try m.parse(a,"__This will be bold__");defer a.free(out);try t.expectEqualStrings("<p><strong>This will be bold</strong></p>",out);}
test "test_mixed_normal_italics_and_bold_text" {const out=try m.parse(a,"This will _be_ __mixed__");defer a.free(out);try t.expectEqualStrings("<p>This will <em>be</em> <strong>mixed</strong></p>",out);}
test "test_with_h1_header_level" {const out=try m.parse(a,"# This will be an h1");defer a.free(out);try t.expectEqualStrings("<h1>This will be an h1</h1>",out);}
test "test_with_h2_header_level" {const out=try m.parse(a,"## This will be an h2");defer a.free(out);try t.expectEqualStrings("<h2>This will be an h2</h2>",out);}
test "test_with_h3_header_level" {const out=try m.parse(a,"### This will be an h3");defer a.free(out);try t.expectEqualStrings("<h3>This will be an h3</h3>",out);}
test "test_with_h4_header_level" {const out=try m.parse(a,"#### This will be an h4");defer a.free(out);try t.expectEqualStrings("<h4>This will be an h4</h4>",out);}
test "test_with_h5_header_level" {const out=try m.parse(a,"##### This will be an h5");defer a.free(out);try t.expectEqualStrings("<h5>This will be an h5</h5>",out);}
test "test_with_h6_header_level" {const out=try m.parse(a,"###### This will be an h6");defer a.free(out);try t.expectEqualStrings("<h6>This will be an h6</h6>",out);}
test "test_h7_header_level_is_a_paragraph" {const out=try m.parse(a,"####### This will not be an h7");defer a.free(out);try t.expectEqualStrings("<p>####### This will not be an h7</p>",out);}
test "test_unordered_lists" {const out=try m.parse(a,"* Item 1\n* Item 2");defer a.free(out);try t.expectEqualStrings("<ul><li>Item 1</li><li>Item 2</li></ul>",out);}
test "test_with_a_little_bit_of_everything" {const out=try m.parse(a,"# Header!\n* __Bold Item__\n* _Italic Item_");defer a.free(out);try t.expectEqualStrings("<h1>Header!</h1><ul><li><strong>Bold Item</strong></li><li><em>Italic Item</em></li></ul>",out);}
test "test_with_markdown_symbols_in_the_header_text_that_should_not_be_interpreted" {const out=try m.parse(a,"# This is a header with # and * in the text");defer a.free(out);try t.expectEqualStrings("<h1>This is a header with # and * in the text</h1>",out);}
test "test_with_markdown_symbols_in_the_list_item_text_that_should_not_be_interpreted" {const out=try m.parse(a,"* Item 1 with a # in the text\n* Item 2 with * in the text");defer a.free(out);try t.expectEqualStrings("<ul><li>Item 1 with a # in the text</li><li>Item 2 with * in the text</li></ul>",out);}
test "test_with_markdown_symbols_in_the_paragraph_text_that_should_not_be_interpreted" {const out=try m.parse(a,"This is a paragraph with # and * in the text");defer a.free(out);try t.expectEqualStrings("<p>This is a paragraph with # and * in the text</p>",out);}
test "test_unordered_lists_close_properly_with_preceding_and_following_lines" {const out=try m.parse(a,"# Start a list\n* Item 1\n* Item 2\nEnd a list");defer a.free(out);try t.expectEqualStrings("<h1>Start a list</h1><ul><li>Item 1</li><li>Item 2</li></ul><p>End a list</p>",out);}
